static List_u8* clone_Lu8(List_u8* v, RtMem* mem, RtCloneMap* cm) {
    (void)cm;
    if (rt_clone_keeps(cm, v)) return v;
    if (cm->only) { void* done = rt_clone_get(cm, v); if (done) return (List_u8*)done; }
    List_u8* r = List_u8_new(mem, 0);
    if (cm->only) rt_clone_put(cm, v, r);
    for (int32_t i = 0; i < v->length; i++) List_u8_add(r, v->items[i], 0);
    return r;
}

